import { _decorator, Component } from 'cc';
import { Quest, QuestList, QuestObjectiveCollect, QuestObjectiveKill } from './Quests';
import { EventBus, GameEvents } from '../core/EventBus';
import { Inventory } from '../inventory/Inventory';
import { PlayerStats } from '../player/PlayerStats';
import { ItemDB } from '../inventory/Items';
const { ccclass } = _decorator;

@ccclass('QuestManager')
export class QuestManager extends Component {
    public quests: Quest[] = [];
    public inventory: Inventory | null = null;
    public stats: PlayerStats | null = null;

    onLoad() {
        // Deep clone the static list so progress is isolated
        this.quests = QuestList.map(q => JSON.parse(JSON.stringify(q)));

        EventBus.on(GameEvents.ENEMY_DIED, this.onEnemyDied.bind(this));
        EventBus.on(GameEvents.INVENTORY_CHANGED, this.refreshCollectProgress.bind(this));
    }

    private onEnemyDied(enemy: any) {
        const kind = enemy?.archetype?.kind;
        if (!kind) return;
        for (const q of this.quests) {
            if (q.state !== 'active') continue;
            for (const obj of q.objectives) {
                if (obj.type === 'kill' && obj.target === kind && obj.current < obj.required) {
                    obj.current++;
                    EventBus.emit(GameEvents.QUEST_UPDATED, q);
                }
            }
            this.checkReady(q);
        }
    }

    refreshCollectProgress() {
        if (!this.inventory) return;
        for (const q of this.quests) {
            if (q.state !== 'active') continue;
            this.checkReady(q);
            EventBus.emit(GameEvents.QUEST_UPDATED, q);
        }
    }

    private isObjectiveDone(q: Quest, obj: any): boolean {
        if (obj.type === 'kill') return obj.current >= obj.required;
        if (obj.type === 'collect') return !!this.inventory && this.inventory.countItem((obj as QuestObjectiveCollect).itemId) >= (obj as QuestObjectiveCollect).required;
        if (obj.type === 'talk') return obj.done;
        return false;
    }

    private checkReady(q: Quest) {
        const all = q.objectives.every(o => this.isObjectiveDone(q, o));
        if (all) q.state = 'ready';
    }

    canAccept(q: Quest): boolean {
        if (q.state !== 'available') return false;
        if (q.prerequisite) {
            const pre = this.quests.find(x => x.id === q.prerequisite);
            if (!pre || pre.state !== 'completed') return false;
        }
        return true;
    }

    accept(qid: string): boolean {
        const q = this.quests.find(x => x.id === qid);
        if (!q || !this.canAccept(q)) return false;
        q.state = 'active';
        EventBus.emit(GameEvents.QUEST_STARTED, q);
        this.refreshCollectProgress();
        return true;
    }

    turnIn(qid: string): boolean {
        const q = this.quests.find(x => x.id === qid);
        if (!q || q.state !== 'ready' || !this.inventory || !this.stats) return false;
        // Consume collect objectives
        for (const obj of q.objectives) {
            if (obj.type === 'collect') {
                this.inventory.removeItem(obj.itemId, obj.required);
            }
        }
        // Reward
        if (q.reward.exp) this.stats.gainExp(q.reward.exp);
        if (q.reward.gold) this.stats.addGold(q.reward.gold);
        if (q.reward.items) for (const r of q.reward.items) this.inventory.addItem(r.id, r.count);
        q.state = 'completed';
        EventBus.emit(GameEvents.QUEST_COMPLETED, q);
        return true;
    }

    questsForNpc(npcId: string): { available: Quest[]; active: Quest[]; ready: Quest[] } {
        const available = this.quests.filter(q => q.giverNpcId === npcId && this.canAccept(q));
        const active = this.quests.filter(q => q.giverNpcId === npcId && q.state === 'active');
        const ready = this.quests.filter(q => q.giverNpcId === npcId && q.state === 'ready');
        return { available, active, ready };
    }
}